int longestValidParentheses(char *s) {
  int n = strlen(s);
  int *stack = (int *)malloc(sizeof(int) * (n + 1));
  int top = -1;
  stack[++top] = -1;
  int best = 0;
  for (int i = 0; i < n; i++) {
    if (s[i] == '(') {
      stack[++top] = i;
    } else {
      top--;
      if (top == -1) {
        stack[++top] = i;
      } else {
        int len = i - stack[top];
        if (len > best) {
          best = len;
        }
      }
    }
  }
  free(stack);
  return best;
}

class Solution {
public:
  int longestValidParentheses(string s) {
    int best = 0;
    stack<int> stk;
    stk.push(-1);
    for (int i = 0; i < (int)s.size(); i++) {
      if (s[i] == '(') {
        stk.push(i);
      } else {
        stk.pop();
        if (stk.empty()) {
          stk.push(i);
        } else {
          best = max(best, i - stk.top());
        }
      }
    }
    return best;
  }
};

func longestValidParentheses(s string) int {
	stack := []int{-1}
	best := 0
	for i := 0; i < len(s); i++ {
		if s[i] == '(' {
			stack = append(stack, i)
		} else {
			stack = stack[:len(stack)-1]
			if len(stack) == 0 {
				stack = append(stack, i)
			} else if l := i - stack[len(stack)-1]; l > best {
				best = l
			}
		}
	}
	return best
}

class Solution {
  public int longestValidParentheses(String s) {
    int best = 0;
    Deque<Integer> stack = new ArrayDeque<>();
    stack.push(-1);
    for (int i = 0; i < s.length(); i++) {
      if (s.charAt(i) == '(') {
        stack.push(i);
      } else {
        stack.pop();
        if (stack.isEmpty()) {
          stack.push(i);
        } else {
          best = Math.max(best, i - stack.peek());
        }
      }
    }
    return best;
  }
}

class Solution:
    def longestValidParentheses(self, s: str) -> int:
        stack = [-1]
        best = 0
        for i, ch in enumerate(s):
            if ch == '(':
                stack.append(i)
            else:
                stack.pop()
                if not stack:
                    stack.append(i)
                else:
                    best = max(best, i - stack[-1])
        return best

impl Solution {
  pub fn longest_valid_parentheses(s: String) -> i32 {
    let mut stack: Vec<i32> = vec![-1];
    let mut best = 0;
    for (i, c) in s.chars().enumerate() {
      if c == '(' {
        stack.push(i as i32);
      } else {
        stack.pop();
        if stack.is_empty() {
          stack.push(i as i32);
        } else {
          best = best.max(i as i32 - stack[stack.len() - 1]);
        }
      }
    }
    best
  }
}

const longestValidParentheses = (s: string): number => {
  const stack: number[] = [-1];
  let best = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '(') {
      stack.push(i);
    } else {
      stack.pop();
      if (stack.length === 0) {
        stack.push(i);
      } else {
        best = Math.max(best, i - stack[stack.length - 1]);
      }
    }
  }
  return best;
};
